"""Computes the integral of f in [a, b] with step size h."""
def riemann_sum(f: Any, a: Any, b: Any, h: Any) -> object {
    assert (h > 0) , 'Step size must be a positive number!';
    s = 0;
    x = a + (h / 2);
    while (x < b) {
        s += h * f(x);
        x += h;
    }
    return s;
}

test_blocks:
test "t0" {
    assert (riemann_sum(lambda (x: Any) { (x ** 2); }, 1, 4, 4) == 36);;
}

test "t1" {
    assert (riemann_sum(lambda (x: Any) { x; }, 1, 3, 1) == 4);;
}

test "t2" {
    assert (riemann_sum(lambda (x: Any) { (1 / x); }, 2, 1, 0.001) == 0);;
}

test "t3" {
    assert (riemann_sum(lambda (x: Any) { x; }, 0, 1, 0.1) == 0.5);;
}

test "t4" {
    assert (riemann_sum(lambda (x: Any) { 5; }, 0, 10, 1) == 50);;
}

test "t5" {
    assert (riemann_sum(lambda (x: Any) { 1; }, 0, 4, 1) == 4);;
}

test "t6" {
    assert (riemann_sum(lambda (x: Any) { (2 * x); }, 1, 3, 1) == 8);;
}

test "t7" {
    assert (riemann_sum(lambda (x: Any) { x; }, 2, 3, 0.5) == 2.5);;
}
